CREATE TABLE IF NOT EXISTS settings (id VARCHAR(64) PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS branches (id VARCHAR(64) PRIMARY KEY, name VARCHAR(200) NOT NULL, company VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(300) NOT NULL, role VARCHAR(30) NOT NULL, branch_id VARCHAR(64) NOT NULL, active BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS patients (id VARCHAR(64) PRIMARY KEY, name VARCHAR(200) NOT NULL, phone VARCHAR(40) NOT NULL, birth_date VARCHAR(10) NOT NULL, allergies TEXT NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS services (id VARCHAR(64) PRIMARY KEY, name VARCHAR(200) NOT NULL, category VARCHAR(30) NOT NULL, price BIGINT NOT NULL, doctor_bp BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id VARCHAR(64) PRIMARY KEY, name VARCHAR(200) NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visits (id VARCHAR(64) PRIMARY KEY, branch_id VARCHAR(64) NOT NULL, patient_id VARCHAR(64) NOT NULL, doctor_id VARCHAR(64) NOT NULL, payload TEXT NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id VARCHAR(64) PRIMARY KEY, branch_id VARCHAR(64) NOT NULL, kind VARCHAR(30) NOT NULL, party VARCHAR(200) NOT NULL, visit_id VARCHAR(64) NOT NULL, payload TEXT NOT NULL, total BIGINT NOT NULL, patient_due BIGINT NOT NULL, insurer_due BIGINT NOT NULL, doctor_due BIGINT NOT NULL, status VARCHAR(30) NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id VARCHAR(64) PRIMARY KEY, name VARCHAR(200) NOT NULL, category VARCHAR(30) NOT NULL, parent_id VARCHAR(64) NOT NULL, postable BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS journals (id VARCHAR(64) PRIMARY KEY, branch_id VARCHAR(64) NOT NULL, source_id VARCHAR(64) NOT NULL, memo VARCHAR(400) NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS journal_lines (id VARCHAR(64) PRIMARY KEY, journal_id VARCHAR(64) NOT NULL, account_id VARCHAR(64) NOT NULL, debit BIGINT NOT NULL, credit BIGINT NOT NULL, party VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id VARCHAR(64) PRIMARY KEY, document_id VARCHAR(64) NOT NULL, branch_id VARCHAR(64) NOT NULL, payer VARCHAR(30) NOT NULL, amount BIGINT NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, action VARCHAR(100) NOT NULL, entity_id VARCHAR(64) NOT NULL, branch_id VARCHAR(64) NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, fingerprint VARCHAR(64) NOT NULL, payload TEXT NOT NULL);
